/**
 * Black-Box API Integration Test (template-rendered v2)
 *
 * @target-controller CommunityController (src/main/java/com/tainted/community/web/CommunityController.java)
 * @target-api GET /internal/posts
 *
 * GET /internal/posts: no request params. Returns all posts ordered by createdAt DESC (PostRepository.findAllByOrderByCreatedAtDesc).
 * analyze-auth-flow: auth_type=none (no interceptor/filter). detect-external-calls --include-di-analysis: must_mock=[] (Kafka publisher is non-HTTP, kept REAL per core-principle #4).
 * generate-test-plan's generic ATC_code400 is not reachable here (no request params, no validation annotations on this handler) -- intentionally not rendered as a fabricated test (Zero-Hallucination).
 * Literal (non-testId) seed IDs used throughout: template-render v2 does not substitute ${} inside expectBody assertions, so exact-match assertions require values known at spec-authoring time. Uniqueness is authored via distinct literal prefixes (lp-*).
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class CommunityListPostsBlackBoxTest {

    private Map<String, String> seed(TestInfo info) {
        return Map.of(
);
    }

    private void arrange(Map<String, String> p) {
        executeSqlTemplate("sql/community-list-posts-teardown.sql", p);
        executeSqlTemplate("sql/community-list-posts-setup.sql", p);
    }

    @Test
    void NTC_listPosts_singleSeededPostFieldsMatch(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
            .when()
                    .get("/internal/posts")
            .then()
                    .statusCode(200)
                    .body("find { it.id == 'lp-single-01' }.userId", equalTo("user-lp-single"))
                    .body("find { it.id == 'lp-single-01' }.title", equalTo("Single Seeded Post"))
                    .body("find { it.id == 'lp-single-01' }.category", equalTo("career"))
                    .body("find { it.id == 'lp-single-01' }.content", equalTo("single content body"))
                    .body("find { it.id == 'lp-single-01' }.moodEmoji", equalTo("🙂"))
                    .body("find { it.id == 'lp-single-01' }.nickname", equalTo("singleNick"))
                    .body("find { it.id == 'lp-single-01' }.likes", equalTo(0))
                    .body("find { it.id == 'lp-single-01' }.createdAt", containsString("2024-03-01"));
        } finally {
            executeSqlTemplate("sql/community-list-posts-teardown.sql", p);
        }
    }

    @Test
    void NTC_listPosts_orderedByCreatedAtDesc(TestInfo info) {
        // two seeded posts with distinct created_at -- newer must precede older in the DESC-ordered response
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
            .when()
                    .get("/internal/posts")
            .then()
                    .statusCode(200)
                    .body("findAll { it.id in ['lp-old-01','lp-new-01'] }[0].id", equalTo("lp-new-01"))
                    .body("findAll { it.id in ['lp-old-01','lp-new-01'] }[1].id", equalTo("lp-old-01"));
        } finally {
            executeSqlTemplate("sql/community-list-posts-teardown.sql", p);
        }
    }

    @Test
    void NTC_listPosts_likesCountReflected(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
            .when()
                    .get("/internal/posts")
            .then()
                    .statusCode(200)
                    .body("find { it.id == 'lp-likes-01' }.userId", equalTo("user-lp-likes"))
                    .body("find { it.id == 'lp-likes-01' }.likes", equalTo(7))
                    .body("find { it.id == 'lp-likes-01' }.category", equalTo("mental"));
        } finally {
            executeSqlTemplate("sql/community-list-posts-teardown.sql", p);
        }
    }
}

