    "handler": "getPost"
  },
  "className": "CommunityGetPostBlackBoxTest",
  "sqlSlug": "community-get-post",
  "docLines": [
    "GET /internal/posts/{id}: PostRepository.findById(id).orElseThrow(PostNotFoundException) -- 404 application/problem+json on miss.",
    "extract-key-params flagged id as RED (DB_WHERE). generate-vtc-from-red-params proposed NULL/EMPTY/WHITE_SPACE/SPECIAL_CHAR + 6 API-level mutations; adapted to this GET+path-variable shape (calibration snippets are for a different SUT and were not copied verbatim):",
    "  - NULL: not reachable -- omitting the path segment routes to GET /internal/posts (listPosts), a different handler entirely. Not rendered.",
    "  - EMPTY: trailing-slash route-matching behavior is not verifiable via static analysis alone (Step 6 execution is out of scope for this run). Not rendered rather than guessing a status code.",
    "  - WHITE_SPACE/SPECIAL_CHAR/LENGTH_EXCEEDED(overflow)/XSS -> all reach findById() safely (JPA uses parameterized queries) and deterministically 404 with a precise 'post not found: <id>' detail -- rendered below.",
    "  - emptyBody/badHeader/structureTamper: not applicable (GET has no request body). wrongMethod: template-render v2 fixes the HTTP method at the class/spec level, so a differing method cannot be expressed in this spec.",
    "analyze-auth-flow: auth_type=none. detect-external-calls: must_mock=[]."
  ],
  "seedParams": [],
  "auth": { "pattern": "none" },
  "fixtures": {
    "setup": [
      { "table": "post", "values": { "id": "gp-found-01", "user_id": "user-gp-found", "title": "Get Post Found Title", "category": "mental", "content": "Get post found content body", "mood_emoji": "😪", "nickname": "gpNick", "likes": 3, "created_at": { "expr": "'2024-02-01 00:00:00'" } } },
      { "table": "post", "values": { "id": "gp-family-01", "user_id": "user-gp-family", "title": "Get Post Family Title", "category": "family", "content": "Get post family content body", "mood_emoji": "😟", "nickname": "gpFamilyNick", "likes": 0, "created_at": { "expr": "'2024-02-02 00:00:00'" } } },
      { "table": "post", "values": { "id": "gp-rel-01", "user_id": "user-gp-rel", "title": "Get Post Relationship Title", "category": "relationship", "content": "Get post relationship content body", "mood_emoji": "😶", "nickname": "gpRelNick", "likes": 42, "created_at": { "expr": "'2024-02-03 00:00:00'" } } }
    ],
    "teardown": [
      { "table": "post", "where": { "id": "gp-found-01" } },
      { "table": "post", "where": { "id": "gp-family-01" } },
      { "table": "post", "where": { "id": "gp-rel-01" } }
    ],
    "preDelete": true
  },
  "tests": [
    {
      "name": "NTC_getPost_found",
      "pathParams": { "id": "gp-found-01" },
      "expectStatus": 200,
      "expectBody": [
        { "path": "id", "equalTo": "gp-found-01" },
        { "path": "userId", "equalTo": "user-gp-found" },
        { "path": "title", "equalTo": "Get Post Found Title" },
        { "path": "category", "equalTo": "mental" },
        { "path": "content", "equalTo": "Get post found content body" },
        { "path": "moodEmoji", "equalTo": "😪" },
        { "path": "nickname", "equalTo": "gpNick" },
        { "path": "likes", "equalToInt": 3 },
        { "path": "createdAt", "containsString": "2024-02-01" }
      ]
    },
    {
      "name": "NTC_getPost_familyCategoryZeroLikes",
      "pathParams": { "id": "gp-family-01" },
      "expectStatus": 200,
      "expectBody": [
        { "path": "id", "equalTo": "gp-family-01" },
        { "path": "category", "equalTo": "family" },
        { "path": "moodEmoji", "equalTo": "😟" },
        { "path": "likes", "equalToInt": 0 }
      ]
    },
    {
      "name": "NTC_getPost_relationshipCategoryHighLikes",
      "pathParams": { "id": "gp-rel-01" },
      "expectStatus": 200,
      "expectBody": [
        { "path": "id", "equalTo": "gp-rel-01" },
        { "path": "category", "equalTo": "relationship" },
        { "path": "nickname", "equalTo": "gpRelNick" },
        { "path": "likes", "equalToInt": 42 }
      ]
    },
    {
      "name": "ATC_getPost_notFound",
      "pathParams": { "id": "gp-missing-01" },
      "expectStatus": 404,
      "expectBody": [
        { "path": "title", "equalTo": "Post not found" },
        { "path": "status", "equalToInt": 404 },
        { "path": "detail", "equalTo": "post not found: gp-missing-01" }
      ]
    },
    {
      "name": "VTC_id_WHITE_SPACE",
      "comment": "single-space id -- valid non-empty path segment, findById returns empty -> 404",
      "pathParams": { "id": " " },
      "expectStatus": 404,
      "expectBody": [
        { "path": "detail", "equalTo": "post not found:  " }
      ]
    },
    {
      "name": "VTC_id_SPECIAL_CHAR",
      "comment": "SQL-injection-shaped id -- JPA findById is parameterized, so this is a safe not-found, not a 500",
      "pathParams": { "id": "'; DROP TABLE --" },
      "expectStatus": 404,
      "expectBody": [
        { "path": "detail", "equalTo": "post not found: '; DROP TABLE --" }
      ]
    },
    {
      "name": "VTC_id_LENGTH_EXCEEDED",
      "comment": "id far exceeding the post.id VARCHAR(64) column length -- not an INSERT, so no truncation/DB error, just no match",
      "pathParams": { "id": "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx" },
      "expectStatus": 404,
      "expectBody": [
        { "path": "detail", "equalTo": "post not found: xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx" }
      ]
    },
    {
      "name": "VTC_id_XSS_PAYLOAD",
      "pathParams": { "id": "<script>alert('xss')</script>" },
      "expectStatus": 404,
      "expectBody": [
        { "path": "detail", "equalTo": "post not found: <script>alert('xss')</script>" }
      ]
    }
  ]
}

